class Solution:
    def minNumberOfFrogs(self, croakOfFrogs: str) -> int:
        idx = {ch: i for i, ch in enumerate("croak")}
        cnt = [0] * 4
        frogs = ans = 0
        for ch in croakOfFrogs:
            i = idx[ch]
            if i == 0:
                cnt[0] += 1
                frogs += 1
                ans = max(ans, frogs)
            else:
                if cnt[i - 1] == 0:
                    return -1
                cnt[i - 1] -= 1
                if i < 4:
                    cnt[i] += 1
                else:
                    frogs -= 1
        return ans if frogs == 0 else -1

