class Solution {
public:
    int minNumberOfFrogs(string croakOfFrogs) {
        string s = "croak";
        vector<int> cnt(4, 0);
        int frogs = 0, ans = 0;
        for (char ch : croakOfFrogs) {
            int i = s.find(ch);
            if (i == 0) {
                cnt[0]++;
                frogs++;
                ans = max(ans, frogs);
            } else {
                if (cnt[i - 1] == 0) return -1;
                cnt[i - 1]--;
                if (i < 4) cnt[i]++;
                else frogs--;
            }
        }
        return frogs == 0 ? ans : -1;
    }
};

