        prev = {'r': 'c', 'o': 'r', 'a': 'o', 'k': 'a'}
        ans = 0
        for ch in croakOfFrogs:
            p = prev.get(ch)
            if p and cnt[p] == cnt[ch]:
                return -1
            cnt[ch] += 1
            ans = max(ans, cnt['c'] - cnt['k'])
        return ans if len(set(cnt.values())) == 1 else -1

