class Solution {
    public int minNumberOfFrogs(String croakOfFrogs) {
        int[] cnt = new int[5];
        String s = "croak";
        int ans = 0;
        for (char ch : croakOfFrogs.toCharArray()) {
            int i = s.indexOf(ch);
            if (i > 0 && cnt[i - 1] == cnt[i]) return -1;
            cnt[i]++;
            ans = Math.max(ans, cnt[0] - cnt[4]);
        }
        for (int i = 1; i < 5; i++) if (cnt[i] != cnt[0]) return -1;
        return ans;
    }
}

